fn midpoint(v: &Vec[Int]) -> Int {
  let mid = v.len() / 2;
  return v.slice(mid, mid + 1)[0];
}

fn is_sorted(v: &Vec[Int], start: Int, end: Int) -> Bool {
  let slice = v.slice(start, end);
  if slice.len() <= 1 { return true; }
  var i = 1;
  while i < slice.len() {
    if slice[i - 1] > slice[i] { return false; }
    i = i + 1;
  }
  return true;
}

fn main() -> Int {
  let v = Vec[Int]();
  v.push(1); v.push(2); v.push(3); v.push(4); v.push(5);
  return midpoint(&v);
}
